// Shape the trigger item into one message, and decide whether to stay silent.
//
// The two deliberate throws already alert on their own path before throwing:
//   ThrowDbOutage        EmailDbOutage has emailed with the lead's message verbatim
//   ThrowKeepaliveFailure the keepalive emailed AND messaged, then threw so the
//                         execution is recorded as failed (the pull signal)
// Reporting them again here is a second alert for one fact, which is how
// alerting gets muted. Named, not pattern-matched, like the zone table.
const j = $input.first().json || {};
const ex = j.execution || {};
const wf = j.workflow || {};
const tr = j.trigger || {};
const err = ex.error || tr.error || {};
const node = ex.lastNodeExecuted || (tr.error ? 'trigger' : 'unknown');
// n8n hands the Code node's error with `message` cut to the text after the last
// colon -- the probe's 'error probe: ... (2026-09-16T11:10:55.836Z)' arrived as
// '55.836Z) [line 2]' (proof run, 16 Sep). The first line of the stack still
// carries it whole, so the longer of the two is the message.
const fromMsg = String(err.message || err.description || '');
const fromStack = String(err.stack || '').split('\n')[0].replace(/^[A-Za-z]*Error:\s*/, '');
const line = err.lineNumber != null ? ' [line ' + err.lineNumber + ']' : '';
const message = ((fromStack.length > fromMsg.length ? fromStack + line : fromMsg) || 'no message').slice(0, 400);
const stack = String(err.stack || '').split('\n').slice(0, 4).join('\n').slice(0, 600);
const SUPPRESS = {
  ThrowDbOutage: 'EmailDbOutage already emailed, with the lead message verbatim',
  ThrowKeepaliveFailure: 'the keepalive already emailed and messaged before throwing',
};
const suppressed = SUPPRESS[node] || null;
const at = new Date().toISOString();
const name = wf.name || wf.id || 'unknown workflow';
const subject = 'Ryvo RUN ERROR: ' + name + ' at ' + node;
const text = [
  'An n8n execution ended in error. The node threw with no error branch, so no',
  'run row and no handoff came out of it: whatever this run was doing for a lead',
  'did not happen, and nobody was told except by this message.',
  '',
  'Workflow:  ' + name + ' (' + (wf.id || '?') + ')',
  'Node:      ' + node,
  'Mode:      ' + (ex.mode || tr.mode || '?'),
  'Execution: ' + (ex.id || '?') + (ex.url ? '  ' + ex.url : ''),
  'At:        ' + at,
  '',
  'Error: ' + message,
  stack ? '\n' + stack : '',
].join('\n');
const wa = 'Ryvo run error\n' + name + '\nnode: ' + node + '\n' + message.slice(0, 220) + (ex.url ? '\n' + ex.url : '');
return [{ json: { workflowId: wf.id || null, workflowName: name, node, message, executionId: ex.id || null,
                  executionUrl: ex.url || null, mode: ex.mode || tr.mode || null, suppressed, subject, text, wa, at } }];

// Recorded, not sent. The execution shows WHY nothing went out.
const s = $('ShapeError').first().json;
return [{ json: { suppressed: true, node: s.node, reason: s.suppressed, workflow: s.workflowName, executionId: s.executionId } }];

// A send that was not accepted must not look like one that was. If NEITHER
// channel accepted the alert, this execution fails with the reason, so the
// handler's own list shows it. One accepted channel is a delivered alert.
const code = (n) => { try { const r = $(n).first().json || {}; return r.statusCode == null ? null : Number(r.statusCode); } catch (e) { return null; } };
const ok = (c) => c !== null && c >= 200 && c < 300;
const email = code('EmailError'), wa = code('NotifyError'), ev = code('RecordEvent');
const s = $('ShapeError').first().json;
if (!ok(email) && !ok(wa)) {
  throw new Error('RUN ERROR ALERT NOT DELIVERED for ' + s.workflowName + ' at ' + s.node
    + ': email HTTP ' + email + ', WhatsApp HTTP ' + wa + ', event HTTP ' + ev + '. Original error: ' + s.message);
}
return [{ json: { delivered: true, emailStatus: email, whatsappStatus: wa, eventStatus: ev, workflow: s.workflowName, node: s.node, executionId: s.executionId } }];
